class Rodzic {
  constructor(x) {
    this.x = x;
  }
}

class Dziecko extends Rodzic {
  constructor(x, y) {
    // this.y = y; -- BLAD: must call super constructor before accessing 'this'
    super(x); // POPRAWNIE - musi byc PIERWSZE
    this.y = y; // teraz bezpieczne
  }
}

// this (nowo tworzona instancja) nie jest w pelni "gotowe", dopoki czesc
// pochodzaca od rodzica (pola ustawiane przez constructor klasy bazowej)
// nie zostanie zainicjalizowana przez super(). JavaScript wymusza te
// kolejnosc, rzucajac blad przy kazdej probie uzycia this przed super()
// w konstruktorze klasy, ktora dziedziczy po innej (extends).

class Zwierze {
  dzwiek() {
    return "...";
  }
}
class Pies extends Zwierze {
  dzwiek() {
    return "hau";
  }
}
class Kot extends Zwierze {
  dzwiek() {
    return "miau";
  }
}

const zwierzeta = [new Pies(), new Kot(), new Zwierze()];
console.log(zwierzeta.map(z => z.dzwiek())); // -> ["hau", "miau", "..."]
// Polimorfizm: ta sama metoda dzwiek() zachowuje sie roznie w zaleznosci od klasy obiektu.

